mapper.select:
select mn.*, ci.Ci_id as ciId, ci.Ci_Name as ciName, ci.Ci_Code as ciCode, ci.Ci_Type as ciType, ci.Ci_Expection as ciExpection, ci.Ci_describe as ciDescribe, ci.ci_Indicator as ciIndicator, ci.ci_Method_Data as ciMethodData, ci.Ci_Compute_Expection as ciComputeExpection, su.U_Name as checkPersonUname, pro.p_Id as pId, pro.p_Name as pName, dm.dm_Region_Name as diRegionName, dm.dm_Code as diRegionCode, dm.dm_Id as dmId, dm.dm_Drawing as diDrawing, td.task_Name as taskName, td.task_Code as taskCode, case when mn.measured_Flag = '02' and mn.hf_Hg_Flag = '01' and mn.qsr_Id is null then '01' when mn.measured_Flag = '02' and qr.qsr_Rectify_Status = '02' then '02' when mn.measured_Flag = '02' and qr.qsr_Rectify_Status = '03' then '03' else null end as taskStatus from task_distribution_check mn left join Qs_Record qr on qr.qsr_Id = mn.qsr_Id left join check_item ci on ci.Ci_Id = mn.Ci_Id left join task_distribution td on td.Td_Id = mn.Td_Id left join Drawing_Management_Catalogue dm on dm.dm_Id = td.dm_Id left join sys_user su on su.U_id = mn.Check_Person_Uid left join pre_project pro on pro.p_Id = td.p_Id where td.state = 7
and mn.td_Id = #{params.tdId}
and mn.Check_Person_Uid = #{params.checkPersonUid}
and mn.Check_Type = #{params.checkType}
and mn.Measured_Flag = #{params.measuredFlag}
and su.U_Name like concat('%',#{params.checkPersonUname},'%')
and ci.Ci_Name like concat('%',#{params.ciName},'%')
and ci.Ci_Code like concat('%',#{params.ciCode},'%')
and ci.Ci_Type like concat('%',#{params.ciType},'%')
and ci.Ci_Expection like concat('%',#{params.ciExpection},'%')
and ci.Ci_Compute_Expection like concat('%',#{params.ciComputeExpection},'%')
and td.p_Id = #{params.pId}
and mn.hf_Hg_Flag like concat('%',#{params.hfHgFlag},'%')
order by mn.order_No

select mn.*, mn.task_user_ids as taskUserIds, mn.task_user_names as taskUserNames, pro.p_Id as pId, pro.p_Name as pName, dm.Dm_Drawing as diDrawing, dm.dm_Region_Name as diRegionName, dm.dm_Code as diRegionCode from task_distribution mn left join task_distribution_check tdc on tdc.Td_Id = mn.Td_Id left join Drawing_Management_Catalogue dm on dm.dm_Id = mn.dm_Id left join pre_project pro on pro.p_Id = mn.p_Id where 1=1 and mn.state = 7
and mn.te_Id = #{params.teId}
and ( tdc.Check_Person_Uid = #{params.checkPersonUid} or ( mn.task_user_ids is not null and concat(',', mn.task_user_ids, ',') like concat('%,', #{params.checkPersonUid}, ',%') ) )
and mn.p_Id = #{params.pId}
order by mn.create_Time asc limit 1
